from typing import Tuple, Dict

Belnap = str  # 'N','F','T','B'
TO_PROD: Dict[Belnap, Tuple[bool, bool]] = {
    'N': (False, False), 'F': (False, True),
    'T': (True, False),  'B': (True, True),
}
OF_PROD = {v: k for k, v in TO_PROD.items()}

def neg(a: Belnap) -> Belnap:
    f, g = TO_PROD[a]
    return OF_PROD[(g, f)]

def designated(a: Belnap) -> bool:
    return a in ('T', 'B')

def classify(a: Belnap) -> str:
    if designated(a) and designated(neg(a)):
        return 'GLUT'
    if not designated(a) and not designated(neg(a)):
        return 'GAP'
    return 'PLAIN'

if __name__ == '__main__':
    for a in ('N', 'F', 'T', 'B'):
        print(a, classify(a))

from typing import Callable, List, Optional, Tuple

Belnap = str
VALUES: List[Belnap] = ['N', 'F', 'T', 'B']

def neg(a: Belnap) -> Belnap:
    return {'N': 'N', 'F': 'T', 'T': 'F', 'B': 'B'}[a]

def designated(a: Belnap) -> bool:
    return a in ('T', 'B')

def explosion_witness() -> Optional[Tuple[Belnap, Belnap]]:
    for a in VALUES:
        if designated(a) and designated(neg(a)):
            for q in VALUES:
                if not designated(q):
                    return (a, q)
    return None

if __name__ == '__main__':
    w = explosion_witness()
    print('paraconsistent' if w else 'explosive', 'witness=', w)

